export async function fetchPortal(site: SiteDef): Promise<PortalJob[]> {
  const jobs = await FETCHERS[site.platform](site);
  const skip = site.skipTitles;
  return skip ? jobs.filter((j) => !skip.test(j.t)) : jobs;
}

